export function redRisingImage(category: string, id: string): string {
  const images = imageSets[category] ?? imageSets.concept
  const hash = Array.from(id).reduce((total, character) => total + character.charCodeAt(0), 0)
  return images[hash % images.length]
}


const text = {
  society: "The Society is a color-coded hierarchy spanning the settled solar system. Golds hold political and military power while other Colors are assigned specialized labor, education, and social expectations. Its greatest strength is institutional scale; its central weakness is that it must keep most people divided to remain legitimate.",
  rising: "The Rising is the long revolutionary movement that turns isolated suffering into organized resistance. The saga repeatedly tests whether military victory, political reform, and genuine liberation are the same thing.",
  color: "Color is simultaneously engineered biology, legal status, occupation, and culture. It shapes how a person is educated and treated, but the books also show that Color is not destiny: loyalty, skill, love, and political choice cross the hierarchy.",
  red: "Red miners on Mars extract helium-3 under the belief that they are preparing a future for humanity. Their labor is concealed from them as part of the Society's foundational lie, making Mars both a workplace and the emotional origin of Darrow's rebellion.",
}

