    "rising-concept": { id: "rising-concept", name: "The Rising", summary: "The transition from hidden resistance to open revolutionary war.", definition: text.rising, additionalInfo: "Use separate history records for campaigns and turning points; this concept holds the shared political meaning.", classifications: { scope: ["universal"], effect: ["major"], domain: ["political", "military", "social"], certainty: ["known"] }, fieldValues: { actors: "former subjects, defectors, rebel cells, and allied fleets", risk: "victory can reproduce command and violence", desiredOutcome: "freedom and a new political order" } },
    carving: { id: "carving", name: "Carving", summary: "The surgical and social transformation used to make Darrow pass as Gold.", definition: "Carving is a body-modification technology and political process that alters a person's appearance and capabilities. In Darrow's case it is paired with education, conditioning, and identity performance; the physical change alone is not enough.", additionalInfo: "Distinguish fictional medical procedure from real-world medical claims.", classifications: { scope: ["individual"], effect: ["major"], domain: ["biological", "technological", "political"], certainty: ["known"] }, fieldValues: { inputs: "surgery, genetic expertise, recovery, training", purpose: "infiltration and social access", cost: "pain, risk, identity fracture, and permanent consequences", limitation: "passing requires behavior and knowledge as well as a changed body" } },
    "institute-game": { id: "institute-game", name: "The Institute Game", summary: "A controlled simulation of war used to select and shape Gold leadership.", definition: "The Institute converts education into a resource-limited contest in which students command, ally, betray, and survive. It is both a game with rules and a political laboratory whose graduates carry its assumptions into the wider Society.", additionalInfo: "The record can link to locations, combat doctrines, histories, and character knowledge states.", classifications: { scope: ["regional"], effect: ["major"], domain: ["military", "educational", "political"], certainty: ["known"] }, fieldValues: { inputs: "Gold heirs, territory, scarcity, rules, and observers", outputs: "leaders, alliances, trauma, and political reputation", hiddenAssumption: "competition is treated as evidence of fitness", limit: "the game cannot model the lives of the Colors it excludes" } },
    helldiver: { id: "helldiver", name: "Helldiver", summary: "A Red mining role that carries technical skill, danger, and inherited identity.", definition: "A helldiver works in the dangerous extraction environment beneath Mars. The role is presented to Darrow as a contribution to humanity's future, but the deception surrounding the mines turns the title into a symbol of exploitation and awakening.", additionalInfo: "This is a role and cultural concept, not a species or organization.", classifications: { scope: ["individual", "local"], effect: ["major"], domain: ["economic", "social", "symbolic"], certainty: ["known"] }, fieldValues: { work: "helium-3 extraction", virtues: "skill, courage, and crew loyalty", hazard: "mine collapse and controlled labor", symbol: "the hidden cost of Society expansion" } },
